<?php
namespace App\Services\Examinations;
use App\Enums\ExaminationStatus; use App\Models\Examination; use App\Models\Question; use App\Models\User; use App\Services\QuestionBank\QuestionLocking; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class ExaminationService { public function create(User $u,array $d):Examination {abort_unless($u->teachesOffering((int)$d['class_subject_id']),403);$e=new Examination; $e->fill($d); $e->created_by=$u->id; $e->status=ExaminationStatus::Draft; $e->save(); return $e;} public function syncQuestions(User $u,Examination $e,array $items):void {abort_unless($u->teachesOffering($e->class_subject_id),403);abort_if($e->status!==ExaminationStatus::Draft,422);$ids=array_map('intval',array_column($items,'question_id'));$qs=Question::whereIn('id',$ids)->where('subject_id',$e->classSubject->subject_id)->where('is_active',true)->get()->keyBy('id');if(count($ids)!=$qs->count()||count($ids)!==count(array_unique($ids)))throw ValidationException::withMessages(['questions'=>'Questions must be active, unique, and match the subject.']);DB::transaction(function()use($e,$items,$qs){$e->examinationQuestions()->delete();foreach(array_values($items) as $i=>$item)$e->examinationQuestions()->create(['question_id'=>$item['question_id'],'position'=>$i+1,'points'=>$item['points']??$qs[$item['question_id']]->points]);});} public function publish(User $u,Examination $e):void {abort_unless($u->teachesOffering($e->class_subject_id),403);DB::transaction(function()use($e){$e=Examination::query()->lockForUpdate()->with('examinationQuestions.question')->findOrFail($e->id);if($e->status!==ExaminationStatus::Draft)throw ValidationException::withMessages(['status'=>'Only drafts can be published.']);if(!$e->duration_minutes||$e->examinationQuestions->isEmpty())throw ValidationException::withMessages(['examination'=>'A time limit and at least one question are required.']);$ids=$e->examinationQuestions->pluck('question_id')->all();$rows=app(QuestionLocking::class)->lockRowsForPublication($ids);if($rows->count()!==count($ids)||$rows->contains(fn($q)=>!$q->is_active||$q->subject_id!==$e->classSubject->subject_id))throw ValidationException::withMessages(['questions'=>'Question bank changed; review the exam.']);app(QuestionLocking::class)->lock($ids);$e->update(['status'=>ExaminationStatus::Published]);});} }

